CREATE OR REPLACE FUNCTION public.sync_ask_evidence_count()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE target uuid;
BEGIN
  target := COALESCE(NEW.ask_id, OLD.ask_id);
  UPDATE public.asks a
     SET evidence_count = (SELECT count(*) FROM public.ask_media m WHERE m.ask_id = target),
         updated_at = now()
   WHERE a.id = target;
  RETURN NULL;
END;
$function$

CREATE OR REPLACE FUNCTION public.apply_seller_shipping_defaults()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  handling_days smallint;
  shipping_method text;
BEGIN
  IF coalesce(auth.role(),'')='service_role'
     AND EXISTS(SELECT 1 FROM public.managed_import_sellers WHERE owner_user_id=NEW.seller_id)
     AND current_setting('parkvault.trusted_operation',true)='on' THEN
    NEW.ship_by_days:=coalesce(NEW.ship_by_days,7);
    RETURN NEW;
  END IF;

  IF NEW.in_hand AND NOT NEW.is_demo THEN
    SELECT sp.default_handling_days, sp.default_shipping_method
      INTO handling_days, shipping_method
      FROM public.seller_profiles sp
     WHERE sp.user_id = NEW.seller_id AND sp.status = 'active';
    IF handling_days IS NULL OR shipping_method IS NULL THEN
      RAISE EXCEPTION 'Choose shipping method and handling time in your seller profile before listing';
    END IF;
    NEW.ship_by_days := handling_days;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.clear_ask_sold_at_on_relist()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public'
AS $function$
BEGIN
  IF NEW.status = 'active' AND OLD.status IS DISTINCT FROM 'active' THEN
    NEW.sold_at := NULL;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.guard_ask_user_updates()
 RETURNS trigger
 LANGUAGE plpgsql
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF public.is_trusted_operation() THEN RETURN NEW; END IF;

  IF auth.uid() IS NULL THEN
    RAISE EXCEPTION 'Sign in required';
  END IF;
  IF auth.uid() <> OLD.seller_id OR auth.uid() <> NEW.seller_id THEN
    RAISE EXCEPTION 'Only the Ask owner may change this Ask';
  END IF;

  IF NEW.product_id <> OLD.product_id
     OR NEW.variant_id <> OLD.variant_id
     OR NEW.currency <> OLD.currency
     OR NEW.is_demo <> OLD.is_demo
     OR NEW.in_hand <> OLD.in_hand
     OR NEW.evidence_count <> OLD.evidence_count
     OR COALESCE(NEW.matched_order_id::text, '') <> COALESCE(OLD.matched_order_id::text, '') THEN
    RAISE EXCEPTION 'This field on an Ask is not member-editable';
  END IF;
  IF NEW.status NOT IN ('active', 'cancelled') THEN
    RAISE EXCEPTION 'Members may only cancel an Ask';
  END IF;
  RETURN NEW;
END;
$function$

