CREATE OR REPLACE FUNCTION public.notify_market_interest()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE recipient uuid; product_name text;
BEGIN
  IF NEW.is_demo OR NEW.status <> 'active' THEN RETURN NEW; END IF;
  IF TG_TABLE_NAME = 'asks' AND NEW.approved_at IS NULL THEN RETURN NEW; END IF;
  SELECT name INTO product_name FROM public.products WHERE id = NEW.product_id;
  IF TG_TABLE_NAME = 'bids' THEN
    FOR recipient IN
      SELECT DISTINCT seller_id FROM public.asks
      WHERE variant_id = NEW.variant_id AND status = 'active' AND approved_at IS NOT NULL
        AND expires_at > now() AND seller_id <> NEW.buyer_id
    LOOP
      PERFORM public.notify_member(recipient, 'new_bid', 'New Bid on ' || product_name,
        'A buyer placed a ' || to_char(NEW.price_cents / 100.0, 'FM$999G999G990D00') ||
        ' Bid. Accept it or edit your Ask to counter.', NULL);
    END LOOP;
  ELSE
    FOR recipient IN
      SELECT DISTINCT buyer_id FROM public.bids
      WHERE variant_id = NEW.variant_id AND status = 'active' AND expires_at > now()
        AND buyer_id <> NEW.seller_id
    LOOP
      PERFORM public.notify_member(recipient, 'new_ask', 'New Ask for ' || product_name,
        'A seller listed this item for ' || to_char(NEW.price_cents / 100.0, 'FM$999G999G990D00') || '.', NULL);
    END LOOP;
  END IF;
  RETURN NEW;
END;
$function$

CREATE OR REPLACE FUNCTION public.publish_classified_product_after_approval()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
BEGIN
  IF NEW.status = 'active'
     AND NEW.approved_at IS NOT NULL
     AND NOT NEW.is_demo
     AND EXISTS (
       SELECT 1
       FROM public.classified_listing_details AS details
       WHERE details.listing_id = NEW.id
     ) THEN
    PERFORM set_config('parkvault.trusted_operation', 'on', true);

    UPDATE public.products
    SET status = 'published'::public.product_status
    WHERE id = NEW.product_id
      AND status = 'pending_review'::public.product_status;

    PERFORM set_config('parkvault.trusted_operation', 'off', true);
  END IF;

  RETURN NEW;
EXCEPTION WHEN OTHERS THEN
  PERFORM set_config('parkvault.trusted_operation', 'off', true);
  RAISE;
END;
$function$

CREATE OR REPLACE FUNCTION public.require_verified_seller_for_ask()
 RETURNS trigger
 LANGUAGE plpgsql
 SECURITY DEFINER
 SET search_path TO 'public', 'pg_temp'
AS $function$
DECLARE
  uid uuid := auth.uid();
  seller public.seller_profiles;
BEGIN
  IF uid IS NULL OR NEW.seller_id <> uid THEN
    RETURN NEW;
  END IF;
  SELECT * INTO seller FROM public.seller_profiles WHERE user_id = uid;
  IF seller.user_id IS NULL OR seller.status <> 'active' OR seller.terms_accepted_at IS NULL THEN
    RAISE EXCEPTION 'Complete seller setup before listing';
  END IF;
  RETURN NEW;
END
$function$

